int main(int argc,char**argv){try{std::filesystem::path path="nori-dev-settings.json";std::string png,base,ca;std::filesystem::path vaultpath;bool bench=false;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--settings"&&i+1<argc)path=argv[++i];else if(a=="--render"&&i+1<argc)png=argv[++i];else if(a=="--backend"&&i+1<argc)base=argv[++i];else if(a=="--ca"&&i+1<argc)ca=argv[++i];else if(a=="--vault"&&i+1<argc)vaultpath=argv[++i];else if(a=="--benchmark")bench=true;else{std::cerr<<"Usage: nori_dev_host [--settings PATH] [--render PNG] [--backend HTTPS_URL] [--ca FILE] [--vault PATH] [--benchmark]\n";return 2;}}
auto begin=std::chrono::steady_clock::now();Core core(path);core.start();if(!base.empty()){if(vaultpath.empty()){vaultpath=path;vaultpath += ".vault";}core.configure_auth(base,make_vault(vaultpath),ca);}auto init=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();if(!png.empty()||bench){auto*s=cairo_image_surface_create(CAIRO_FORMAT_ARGB32,1080,700);auto*c=cairo_create(s);auto start=std::chrono::steady_clock::now();int n=bench?300:1;for(int i=0;i<n;i++)render(c,1080,700,core,"");auto ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();if(!png.empty()&&cairo_surface_write_to_png(s,png.c_str())!=CAIRO_STATUS_SUCCESS)throw std::runtime_error("png write failed");struct rusage usage{};getrusage(RUSAGE_SELF,&usage);double cpu=(usage.ru_utime.tv_sec+usage.ru_stime.tv_sec)*1000.0+(usage.ru_utime.tv_usec+usage.ru_stime.tv_usec)/1000.0;std::cout<<"init_ms="<<init<<" frames="<<n<<" draw_total_ms="<<ms<<" draw_avg_ms="<<ms/n<<" peak_rss_kb="<<usage.ru_maxrss<<" cpu_total_ms="<<cpu<<"\n";cairo_destroy(c);cairo_surface_destroy(s);core.stop();return 0;}
Display*d=XOpenDisplay(nullptr);if(!d){std::cerr<<"No X11 display; use --render for a headless preview.\n";return 3;}Bool supported=False;XkbSetDetectableAutoRepeat(d,True,&supported);int scr=DefaultScreen(d);Window win=XCreateSimpleWindow(d,RootWindow(d,scr),10,10,1080,700,0,BlackPixel(d,scr),BlackPixel(d,scr));XStoreName(d,win,"NORI — Development Host (not a game plugin)");XSelectInput(d,win,ExposureMask|StructureNotifyMask|KeyPressMask|KeyReleaseMask|ButtonPressMask);auto close=XInternAtom(d,"WM_DELETE_WINDOW",False);XSetWMProtocols(d,win,&close,1);XMapWindow(d,win);auto*surface=cairo_xlib_surface_create(d,win,DefaultVisual(d,scr),1080,700);auto*cr=cairo_create(surface);int w=1080,h=700;bool running=true,dirty=true;std::string net; unsigned frame=0;
while(running){while(XPending(d)){XEvent e;XNextEvent(d,&e);if(e.type==ClientMessage&&(Atom)e.xclient.data.l[0]==close)running=false;else if(e.type==ConfigureNotify){w=e.xconfigure.width;h=e.xconfigure.height;cairo_xlib_surface_set_size(surface,w,h);dirty=true;}else if(e.type==Expose)dirty=true;else if(e.type==KeyPress||e.type==KeyRelease){auto sym=XLookupKeysym(&e.xkey,0);std::string key=sym==XK_Insert?"Insert":sym==XK_F8?"F8":sym==XK_F9?"F9":sym==XK_F10?"F10":"";if(!key.empty()&&core.input.key(e.type==KeyPress,key,core.settings.hotkey))dirty=true;}else if(e.type==ButtonPress&&core.input.open()){double scale=core.settings.ui_scale/100.0;int x=int(e.xbutton.x/scale),y=int(e.xbutton.y/scale);if(x<224&&y>=108&&y<108+8*48){core.nav.select(static_cast<nori::Screen>((y-108)/48));dirty=true;}else if(core.nav.current()==nori::Screen::License&&core.auth()&&x>=262&&y>=470&&y<558){auto*a=core.auth();if(y<510){if(x<490)a->begin("hassle_rp_2");else if(x<718)a->begin("radmir_crmp");}else if(x<430)a->complete();else if(x<580)a->refresh();else if(x<730)a->cancel();dirty=true;}else if(core.nav.current()==nori::Screen::Settings&&x>=262&&y>=160&&y<390){int row=(y-160)/46;if(row==0){auto&k=core.settings.hotkey;k=k=="Insert"?"F8":k=="F8"?"F9":k=="F9"?"F10":"Insert";}else if(row==1){core.settings.ui_scale=core.settings.ui_scale==150?75:core.settings.ui_scale+25;}else if(row==2)core.settings.notifications=!core.settings.notifications;else if(row==3)core.settings.reduced_motion=!core.settings.reduced_motion;else if(row==4)core.reset();core.save();dirty=true;}}}
if(core.auth()){auto v=core.auth()->view();net=connection_name(v.state);if(++frame%6==0)dirty=true;}if(dirty){render(cr,w,h,core,net);cairo_surface_flush(surface);XFlush(d);dirty=false;}std::this_thread::sleep_for(std::chrono::milliseconds(33));}
core.stop();cairo_destroy(cr);cairo_surface_destroy(surface);XDestroyWindow(d,win);XCloseDisplay(d);return 0;}catch(const std::exception&e){std::cerr<<"Host error: "<<e.what()<<'\n';return 1;}}
